}

async function createBankBuild(user: User, i: { prompt: string; mcVersion: string; want: string }): Promise<CreateBuildResult> {
  const m = matchBank(i.prompt, { mcVersion: i.mcVersion });
  if (!m || m.id !== i.want) return fail(409, { error: "This request no longer matches the ready-made mod. Build it with the AI instead.", code: "bank_mismatch" });
  const served = (await serviceBankEntries()).get(m.id);
  if (!served || (served.length && !served.includes(i.mcVersion))) return fail(409, { error: "The ready-made version of this mod is not available right now. Build it with the AI instead.", code: "bank_unavailable" });
  const id = "mb" + randomBytes(10).toString("hex");
  const gate = await gateBuild({ user, buildId: id, requested: undefined, baseModel: undefined, text: i.prompt, bank: true });
  if (!gate.ok) return fail(gate.status, { error: gate.error, code: gate.code, need: gate.need, available: gate.available, model: gate.model });
  const cyrus: CyrusMeta = { ...(gate.model ? { model: gate.model } : {}), bank: { id: m.id, version: m.version, via: m.via } };
  await cyrusDb.modBuild.create({ data: { id, userId: user.id, prompt: i.prompt, changeRequest: null, baseBuildId: null, rootBuildId: id, mcVersion: i.mcVersion, pluginName: null, cyrus } });
  try {
    await svcCreate({ id, prompt: i.prompt, mcVersion: i.mcVersion, bank: { id: m.id, params: m.params } });
  } catch (e) {
    const msg = e instanceof ModBuilderUnavailable ? "The builder is offline right now. Please try again in a few minutes." : "The builder couldn't take this request. Please try again.";
    await cyrusDb.modBuild.update({ where: { id }, data: { status: "failed", errorCode: "unavailable", error: msg, finishedAt: new Date() } });
    if (gate.tracked) await releaseBuildTokens(id);
    console.error("[modbuilder] bank create failed", id, (e as Error).message);
  }
  await db.auditLog.create({ data: { userId: user.id, action: "modbuilder.build", detail: `${id} bank:${m.id}` } }).catch(() => {});
  const fresh = await cyrusDb.modBuild.findUnique({ where: { id } });
  return { ok: true, status: 201, build: toView(fresh!), reserved: gate.reserved };
}

/**
 * Cyrus r31: build a Designer Studio revision. NO model call (so no tokens are held or charged, and designers are not
 * plan-gated, owner decision): the service copies the base build's workspace, swaps in the revision's designs and
 * compiles them (a config.yml-only edit repacks the base jar with the new config.yml). Same account rules as any build:
 * owned + succeeded base, suspension, game switch, rate limits, at most MAX_INFLIGHT running.
 */
export async function createDesignerBuild(user: User, input: { baseBuildId: string; revisionId: string; seq: number; configOnly: boolean; files: { id: string; spec: unknown }[] }): Promise<CreateBuildResult> {
  const base = await cyrusDb.modBuild.findUnique({ where: { id: input.baseBuildId } });
  if (!base || base.userId !== user.id) return fail(404, { error: "Not found" });
  if (base.status !== "succeeded") return fail(400, { error: "You can only build on a version that has finished. Wait for it to finish, then try again." });
  if (await cyrusSuspension(user.id, "build")) return fail(403, { error: "Building is paused on this account, so nothing was started or charged. Open a support ticket if you think this is a mistake and we will look at it.", code: "suspended" });
  if (!(await cyrusGameBuildable("minecraft"))) return fail(503, { error: "Building for Minecraft is paused for a short while. Nothing was started or charged. Try again later.", code: "game_disabled" });
  if (await cyrusBuildsPaused()) return fail(503, { error: BUILDS_PAUSED_MESSAGE, code: "builds_paused" });
  { const cap = await checkSpendCaps(user.id); if (!cap.ok) return fail(cap.status, { error: cap.error, code: cap.code }); }
  // r51 storage (CYRUS_STORAGE): a full account starts no new build (fails closed); installs and downloads are never gated
  { const st = await checkStorageWrite(user.id, 0, "build"); if (!st.ok) return fail(st.status, { error: st.error, code: st.code }); }
  // D-63: building on an ARCHIVED project brings it back, so it may need its game's slot again
  const slot = await checkGameSlot(user, "minecraft");
  if (!slot.ok) return slotFail(slot);
  for (const [k, max, windowMs] of [["mb:create:min", 3, 60_000], ["mb:create:hour", 20, 3_600_000]] as const) {
    const rl = checkRateLimit(`${k}:${user.id}`, { max, windowMs });
    if (!rl.ok) return fail(429, { error: `You're building fast! Try again in ${rl.retryAfterSec}s.` });
  }
  const inflight = await cyrusDb.modBuild.count({ where: { userId: user.id, status: { notIn: ["succeeded", "failed"] } } });
  if (inflight >= MAX_INFLIGHT) return fail(429, { error: "You already have builds running. Wait for one to finish, or cancel it, then start this one." });
  const id = "mb" + randomBytes(10).toString("hex");
  const changeRequest = `Designer edit: revision ${input.seq}${input.configOnly ? " (settings only)" : ""}`;
  const prev = readCyrusMeta(base.cyrus);
  const cyrus: CyrusMeta = { ...(prev.model ? { model: prev.model } : {}), designer: { revisionId: input.revisionId, seq: input.seq, configOnly: input.configOnly } };
  const createRow = async (c: CyrusDb) => { await c.modBuild.create({ data: { id, userId: user.id, prompt: base.prompt, changeRequest, baseBuildId: base.id, rootBuildId: base.rootBuildId ?? base.id, mcVersion: base.mcVersion, pluginName: base.pluginName, cyrus } }); await unarchiveRoot(base.rootBuildId ?? base.id, c); };
  if (slot.takesSlot) { const claim = await withGameSlot(user, "minecraft", createRow); if (!claim.ok) return slotFail(claim); }
  else await createRow(cyrusDb);
  try {
    await svcCreate({ id, prompt: base.prompt, mcVersion: base.mcVersion, baseBuildId: await serviceBuildId(base.id), changeRequest, designEdit: { revisionId: input.revisionId, files: input.files } });
  } catch (e) {
    const msg = e instanceof ModBuilderUnavailable ? "The builder is offline right now. Please try again in a few minutes." : "The builder couldn't take this request. Please try again.";
    await cyrusDb.modBuild.update({ where: { id }, data: { status: "failed", errorCode: "unavailable", error: msg, finishedAt: new Date() } });
    console.error("[modbuilder] designer build failed", id, (e as Error).message);
  }
  await db.auditLog.create({ data: { userId: user.id, action: "modbuilder.designer_build", detail: id } }).catch(() => {});
  const fresh = await cyrusDb.modBuild.findUnique({ where: { id } });
  return { ok: true, status: 201, build: toView(fresh!), reserved: null };
}

