    // Before the row flips to succeeded (a DB error throws, so the next sync retries; it is idempotent). Builds
    // without assets skip this entirely (no assetResult from the service).
    if (s.assetResult) {
      const assets = await syncBuildAssets({ id: row.id, userId: row.userId, rootBuildId: row.rootBuildId, mcVersion: row.mcVersion, pluginName: s.pluginName || row.pluginName, jarName: s.jar.name, jarSha256: sha, ...(release ? { engineRelease: release } : {}) }, s.assetResult, defaultAssetSyncDeps());
      if (assets) data.result = { ...toResult(s), assets } as unknown as Prisma.InputJsonValue;
      // Cyrus Config Studio: the build's settings schema, validated again (the service is not trusted)
      const cfg = checkReturnedConfig((s.assetResult as { config?: unknown }).config);
      if (cfg) data.result = { ...(data.result as Record<string, unknown>), cyrusConfig: cfg } as unknown as Prisma.InputJsonValue;
    }
  }
  if (isTerminal(s.status)) data.finishedAt = s.finishedAt ? new Date(s.finishedAt) : new Date();
  // Cyrus R5: the engine release record goes on the build's meta for EVERY succeeded build (before the flip, so a
  // succeeded build always has it when the record could be built; a failure here only logs).
  if (release) await mergeCyrusKey(row.id, "engineRelease", release).catch((e) => console.error("[modbuilder] engine release not stored", row.id, (e as Error).message));
  const updated = await cyrusDb.modBuild.update({ where: { id: row.id }, data });
  // Cyrus mods: the first finished version creates the mod's NxLabs page (private
  // by default); every later version regenerates it. Never fails the build.
  if (updated.status === "succeeded") await onBuildSettled(updated).catch(() => {});
  return updated;
}

