"use strict";
// Cyrus capacity (2026-10-14): the build queue's scheduler. PURE (no I/O, the clock is passed in), so the same code runs
// in the service, in the unit tests and in the load simulation (test/modbuilder-capacity.test.ts, scripts/cyrus/queue-sim.ts).
//
// Priority classes:
//   system       guard/planner/health smoke builds (deploy script). Ahead of everything.
//   interactive  portal user builds (the default for any build that names no class: old portals keep working).
//   batch        eval runs, mining jobs, admin re-runs. Explicit `priority: "batch"`, or the id/account prefix fallback
//                (eval runner ids are `ev-<tag>-<hash>`; `eval-`, `eval_`, `mine-`, `batch-` and an `eval:` account too).
//
// Rules (MB_PRIORITY=off turns all of it off: plain FIFO exactly as before this change):
//   1. Reservation: batch builds may run on at most `concurrency - reserve` slots, so the last MB_RESERVE_INTERACTIVE slot(s)
//      are only ever taken by interactive/system work. The reserve is clamped to concurrency - 1 (with one slot there is
//      nothing to reserve: /health says so in capacity.warnings).
//   2. Order: class, then per-account fair share (the account with fewer builds running goes first; ties go to the
//      account that started a build least recently = round robin), then FIFO.
//   3. Starvation guard: a batch build waiting longer than MB_BATCH_STARVE_MIN minutes ranks just ahead of interactive
//      work, but still only on the non-reserved slots, so interactive users keep their reserved slot.
//   4. A build waiting for an AI retry (retryAt in the future) or blocked by the caller's predicate (the AI circuit
//      breaker) is skipped, never failed.

const PRIORITIES = ["system", "interactive", "batch"];
const RANK = { system: 0, interactive: 2, batch: 3 };
const AGED_BATCH_RANK = 1;
const BATCH_ID = /^(ev|eval|mine|batch)[-_]/i;
const ACCOUNT_RE = /^[A-Za-z0-9:_.-]{1,64}$/;

function int(v, d) { const n = parseInt(v == null ? "" : String(v), 10); return Number.isFinite(n) ? n : d; }

/** The class of a new build: explicit `priority`, else the id / account prefix fallback, else interactive. */
function classify(body, id) {
  const raw = body && body.priority !== undefined && body.priority !== null ? String(body.priority).toLowerCase() : "";
  if (raw) {
    if (!PRIORITIES.includes(raw)) return { error: "priority must be interactive, batch or system" };
    return { priority: raw, source: "request" };
  }
  if (BATCH_ID.test(String(id || ""))) return { priority: "batch", source: "id-prefix" };
  if (body && typeof body.account === "string" && /^eval:/i.test(body.account)) return { priority: "batch", source: "account-prefix" };
  return { priority: "interactive", source: "default" };
}

/** Opaque fair-share key: the portal sends a hash of the user id; anything else shares one bucket per class. */
function accountOf(body, priority) {
  const a = body && typeof body.account === "string" ? body.account.trim() : "";
  if (a && ACCOUNT_RE.test(a)) return a;
  return priority === "batch" ? "batch" : "anon";
}

function schedulerConfig(env, concurrency) {
  const c = Math.max(1, int(concurrency, 2));
  const want = Math.max(0, int(env.MB_RESERVE_INTERACTIVE, 1));
  return {
    enabled: env.MB_PRIORITY !== "off",
    concurrency: c,
    reserve: Math.min(want, c - 1),
    reserveWanted: want,
    starveMs: Math.max(1, int(env.MB_BATCH_STARVE_MIN, 30)) * 60_000,
  };
}

function createScheduler(cfg) {
  const items = new Map(); // id -> { id, priority, account, at, seq, retryAt, needsAi }
  const lastStart = new Map(); // account -> start counter (round robin)
  let seq = 0, starts = 0;
  const batchCap = () => (cfg.enabled ? cfg.concurrency - cfg.reserve : cfg.concurrency);
  const rankOf = (it, t) => {
    if (!cfg.enabled) return 0;
    if (it.priority === "batch" && t - it.at >= cfg.starveMs) return AGED_BATCH_RANK;
    return RANK[it.priority] ?? RANK.interactive;
  };
  const activeByAccount = (running) => {
    const m = new Map();
    for (const r of running) m.set(r.account, (m.get(r.account) || 0) + 1);
    return m;
  };
  // Sorted candidates for one pick: class rank, fewer running for the account, least recently served account, FIFO.
  const sorted = (list, active, t, served) => list.slice().sort((a, b) => {
    if (!cfg.enabled) return a.seq - b.seq;
    return rankOf(a, t) - rankOf(b, t)
      || (active.get(a.account) || 0) - (active.get(b.account) || 0)
      || (served.has(a.account) ? served.get(a.account) : -1) - (served.has(b.account) ? served.get(b.account) : -1)
      || a.seq - b.seq;
  });

  return {
    cfg,
    batchCap,
    size: () => items.size,
    has: (id) => items.has(id),
    get: (id) => items.get(id) || null,
    list: () => [...items.values()],
    enqueue(it) {
      const rec = { id: it.id, priority: PRIORITIES.includes(it.priority) ? it.priority : "interactive", account: it.account || "anon", at: it.at ?? 0, seq: ++seq, retryAt: it.retryAt || 0, needsAi: it.needsAi !== false };
      items.set(it.id, rec);
      return rec;
    },
    /** Back in line after an AI-limit failure: keeps its place (original time + sequence), waits until retryAt. */
    requeue(it, retryAt) {
      const prev = items.get(it.id);
      items.set(it.id, { id: it.id, priority: it.priority, account: it.account, at: it.at, seq: it.seq ?? (prev ? prev.seq : ++seq), retryAt: retryAt || 0, needsAi: it.needsAi !== false });
    },
    remove(id) { return items.delete(id); },
    /**
     * Next build to start, or null. `running` = [{ id, priority, account }]. `canStart(item)` is asked in order and the
     * first candidate it accepts wins (the AI circuit breaker lives there; non-AI work is never held back by it).
     */
    pick(running, t, canStart = () => true) {
      if (running.length >= cfg.concurrency) return null;
      const batchRunning = running.filter((r) => r.priority === "batch").length;
      const ready = [...items.values()].filter((it) => !(it.retryAt > t) && (it.priority !== "batch" || !cfg.enabled || batchRunning < batchCap()));
      for (const it of sorted(ready, activeByAccount(running), t, lastStart)) {
        if (!canStart(it)) continue;
        items.delete(it.id);
        lastStart.set(it.account, ++starts);
        return it;
      }
      return null;
    },
    /** The order queued builds would start in if nothing new arrived (positions, estimates). */
    order(running, t) {
      const pending = [...items.values()];
      const active = activeByAccount(running);
      const served = new Map(lastStart);
      let s = starts;
      const out = [];
      while (pending.length) {
        const next = sorted(pending, active, t, served)[0];
        pending.splice(pending.indexOf(next), 1);
        out.push(next);
        active.set(next.account, (active.get(next.account) || 0) + 1);
        served.set(next.account, ++s);
      }
      return out;
    },
    /** 1-based place in line (0 = not queued). */
    position(id, running, t) {
      if (!items.has(id)) return 0;
      return this.order(running, t).findIndex((x) => x.id === id) + 1;
    },
    /**
     * Estimated wait in ms until `id` starts, at one duration quantile `runMs` (p50 or p80 of recent build run times).
     * `running` entries carry startedAt (ms). null when there is no estimate (no samples). Assumes every build ahead takes
     * `runMs`; a running build past `runMs` is assumed to need a little longer (a quarter of runMs), never zero.
     */
    estimate(id, running, t, runMs, extraMs = 0) {
      if (!items.has(id) || !(runMs > 0)) return null;
      const order = this.order(running, t);
      const me = order.find((x) => x.id === id);
      const slots = running.map((r) => ({ at: t + Math.max(runMs - (t - (r.startedAt || t)), runMs / 4), batch: r.priority === "batch" }));
      while (slots.length < cfg.concurrency) slots.push({ at: t, batch: false });
      const cap = batchCap();
      const startOf = (it) => {
        const ready = Math.max(t + extraMs, it.retryAt || 0);
