        return it;
      }
      return null;
    },
    /** The order queued builds would start in if nothing new arrived (positions, estimates). */
    order(running, t) {
      const pending = [...items.values()];
      const active = activeByAccount(running);
      const served = new Map(lastStart);
      let s = starts;
      const out = [];
      while (pending.length) {
        const next = sorted(pending, active, t, served)[0];
        pending.splice(pending.indexOf(next), 1);
        out.push(next);
        active.set(next.account, (active.get(next.account) || 0) + 1);
        served.set(next.account, ++s);
      }
      return out;
    },
    /** 1-based place in line (0 = not queued). */
    position(id, running, t) {
      if (!items.has(id)) return 0;
      return this.order(running, t).findIndex((x) => x.id === id) + 1;
    },
    /**
     * Estimated wait in ms until `id` starts, at one duration quantile `runMs` (p50 or p80 of recent build run times).
     * `running` entries carry startedAt (ms). null when there is no estimate (no samples). Assumes every build ahead takes
     * `runMs`; a running build past `runMs` is assumed to need a little longer (a quarter of runMs), never zero.
     */
    estimate(id, running, t, runMs, extraMs = 0) {
      if (!items.has(id) || !(runMs > 0)) return null;
      const order = this.order(running, t);
      const me = order.find((x) => x.id === id);
      const slots = running.map((r) => ({ at: t + Math.max(runMs - (t - (r.startedAt || t)), runMs / 4), batch: r.priority === "batch" }));
      while (slots.length < cfg.concurrency) slots.push({ at: t, batch: false });
      const cap = batchCap();
      const startOf = (it) => {
        const ready = Math.max(t + extraMs, it.retryAt || 0);
        // a batch build can only take a slot while fewer than `cap` batch builds hold slots
        let cands = slots.map((s, i) => ({ s, i }));
        if (cfg.enabled && it.priority === "batch") {
          const busy = slots.filter((s) => s.batch).length;
          if (busy >= cap) cands = cands.filter((c) => c.s.batch);
        }
        cands.sort((a, b) => a.s.at - b.s.at);
        const c = cands[0];
        const start = Math.max(c.s.at, ready);
        slots[c.i] = { at: start + runMs, batch: it.priority === "batch" };
        return start;
      };
      for (const it of order) {
        const start = startOf(it);
        if (it === me) return Math.max(0, start - t);
      }
      return null;
    },
    stats(running, t) {
      const by = (list) => { const o = { system: 0, interactive: 0, batch: 0 }; for (const x of list) o[x.priority] = (o[x.priority] || 0) + 1; return o; };
      const q = [...items.values()];
      const oldest = q.length ? Math.min(...q.map((x) => x.at)) : null;
      return {
        priority: cfg.enabled, concurrency: cfg.concurrency, reserveInteractive: cfg.enabled ? cfg.reserve : 0, batchCap: batchCap(),
        running: by(running), queued: by(q), waitingForAi: q.filter((x) => x.retryAt > t).length,
        oldestQueuedSec: oldest === null ? null : Math.round((t - oldest) / 1000),
        accounts: new Set(q.concat(running).map((x) => x.account)).size,
      };
    },
  };
}

module.exports = { PRIORITIES, classify, accountOf, schedulerConfig, createScheduler };

