#!/usr/bin/env tsx
// Cyrus capacity: a discrete-event simulation of the build queue with the REAL scheduler (services/modbuilder/scheduler.js),
// fake builds and a fake clock. Zero cost, no service, no model. Used by test/modbuilder-capacity.test.ts and runnable:
//
//   npx tsx scripts/cyrus/queue-sim.ts                     the launch scenario: 3 accounts x 5 builds + 10 batch builds
//   npx tsx scripts/cyrus/queue-sim.ts --concurrency 3 --reserve 1 --fifo
//
// Prints per-class wait percentiles, the start order and the most batch builds that ever ran at once.
import { createRequire } from "node:module";
import path from "node:path";

const req = createRequire(__filename);
// eslint-disable-next-line @typescript-eslint/no-require-imports
const SCH = req(path.join(__dirname, "../../services/modbuilder/scheduler.js")) as {
  createScheduler(cfg: unknown): Scheduler;
  schedulerConfig(env: Record<string, string | undefined>, concurrency: number): unknown;
};

export type Priority = "system" | "interactive" | "batch";
export type SimJob = { id: string; account: string; priority: Priority; arriveSec: number; durSec: number };
export type SimStart = { id: string; account: string; priority: Priority; arriveSec: number; startSec: number; endSec: number; waitSec: number };
type Item = { id: string; priority: Priority; account: string; at: number; seq: number; retryAt: number; needsAi: boolean };
type Run = { id: string; priority: Priority; account: string; startedAt: number };
export type Scheduler = {
  enqueue(it: { id: string; priority: Priority; account: string; at: number }): Item;
  pick(running: Run[], t: number, canStart?: (it: Item) => boolean): Item | null;
  order(running: Run[], t: number): Item[];
  position(id: string, running: Run[], t: number): number;
  estimate(id: string, running: Run[], t: number, runMs: number, extraMs?: number): number | null;
  size(): number;
  batchCap(): number;
};

export type SimOptions = { concurrency: number; env?: Record<string, string | undefined> };
export type SimResult = { starts: SimStart[]; maxBatchRunning: number; makespanSec: number };

export function newScheduler(o: SimOptions): Scheduler {
  return SCH.createScheduler(SCH.schedulerConfig(o.env ?? {}, o.concurrency));
}

/** Run every job through the scheduler; picks happen whenever a build arrives or finishes (as in the service's pump). */
export function simulate(jobs: SimJob[], o: SimOptions): SimResult {
  const S = newScheduler(o);
  const byId = new Map(jobs.map((j) => [j.id, j]));
  const arrivals = jobs.slice().sort((a, b) => a.arriveSec - b.arriveSec);
  const running: (Run & { endMs: number })[] = [];
  const starts: SimStart[] = [];
  let ai = 0, t = 0, maxBatch = 0;
  while (ai < arrivals.length || S.size() || running.length) {
    const nextArrive = ai < arrivals.length ? arrivals[ai].arriveSec * 1000 : Infinity;
    const nextEnd = running.length ? Math.min(...running.map((r) => r.endMs)) : Infinity;
    t = Math.min(nextArrive, nextEnd);
    if (!Number.isFinite(t)) throw new Error("simulation stalled: queued work but nothing can start");
    for (let i = running.length - 1; i >= 0; i--) if (running[i].endMs <= t) running.splice(i, 1);
    while (ai < arrivals.length && arrivals[ai].arriveSec * 1000 <= t) {
      const j = arrivals[ai++];
      S.enqueue({ id: j.id, priority: j.priority, account: j.account, at: j.arriveSec * 1000 });
    }
    for (;;) {
      const it = S.pick(running, t);
      if (!it) break;
      const j = byId.get(it.id)!;
      const endMs = t + j.durSec * 1000;
      running.push({ id: j.id, priority: j.priority, account: j.account, startedAt: t, endMs });
      starts.push({ id: j.id, account: j.account, priority: j.priority, arriveSec: j.arriveSec, startSec: t / 1000, endSec: endMs / 1000, waitSec: t / 1000 - j.arriveSec });
      maxBatch = Math.max(maxBatch, running.filter((r) => r.priority === "batch").length);
    }
  }
  return { starts, maxBatchRunning: maxBatch, makespanSec: t / 1000 };
}

/** Deterministic pseudo-random durations in [lo, hi] seconds (a fixed LCG; the same scenario every run). */
export function durations(n: number, lo: number, hi: number, seed = 7): number[] {
  let x = seed;
  return Array.from({ length: n }, () => { x = (x * 1103515245 + 12345) % 2147483648; return Math.round(lo + (x / 2147483648) * (hi - lo)); });
}

/**
 * The launch scenario: 10 batch builds (an eval run) submitted first, then three accounts each start 5 builds
 * (the first right after the batch, the rest a minute apart). Durations 60-420 s, like the measured p50 150-165 s /
 * p80 ~300 s of evals first1/second1.
 */
export function launchScenario(): SimJob[] {
  const d = durations(25, 60, 420);
  const jobs: SimJob[] = [];
  for (let i = 0; i < 10; i++) jobs.push({ id: `ev-sim-${i}`, account: "eval:sim", priority: "batch", arriveSec: 0, durSec: d[i] });
  ["acct-a", "acct-b", "acct-c"].forEach((a, ai) => {
    for (let k = 0; k < 5; k++) jobs.push({ id: `${a}-${k}`, account: a, priority: "interactive", arriveSec: 5 + ai + k * 60, durSec: d[10 + ai * 5 + k] });
  });
  return jobs;
}

export function pct(xs: number[], p: number): number | null {
  if (!xs.length) return null;
  const s = xs.slice().sort((a, b) => a - b);
  return s[Math.min(s.length - 1, Math.max(0, Math.ceil(p * s.length) - 1))];
}

function main() {
  const a = process.argv.slice(2);
  const opt = (k: string, d: string) => { const i = a.indexOf(`--${k}`); return i >= 0 ? a[i + 1] : d; };
  const concurrency = parseInt(opt("concurrency", "2"), 10);
  const env = { MB_RESERVE_INTERACTIVE: opt("reserve", "1"), MB_BATCH_STARVE_MIN: opt("starve-min", "30"), ...(a.includes("--fifo") ? { MB_PRIORITY: "off" } : {}) };
  const r = simulate(launchScenario(), { concurrency, env });
  const by = (p: Priority) => r.starts.filter((s) => s.priority === p).map((s) => s.waitSec);
  console.log(`concurrency ${concurrency}, reserve ${env.MB_RESERVE_INTERACTIVE}, ${a.includes("--fifo") ? "FIFO (MB_PRIORITY=off)" : "priority + fair share"}`);
  for (const p of ["interactive", "batch"] as const) {
    const w = by(p);
    console.log(`${p.padEnd(11)} n=${w.length} wait p50 ${pct(w, 0.5)} s, p80 ${pct(w, 0.8)} s, max ${pct(w, 1)} s`);
  }
  console.log(`most batch builds running at once: ${r.maxBatchRunning}; all done after ${Math.round(r.makespanSec)} s`);
  console.log("start order:", r.starts.map((s) => s.id).join(" "));
}

if (require.main === module) main();

