// Cyrus capacity queue (2026-10-14): the build service's scheduler (services/modbuilder/scheduler.js) and capacity knobs
// (capacity.js), pure, plus the LOAD TEST with fakes: 3 accounts x 5 builds + 10 batch builds through the real scheduler
// on a fake clock (scripts/cyrus/queue-sim.ts). Zero cost: no service, no model.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { createRequire } from "node:module";
import path from "node:path";
import { simulate, launchScenario, durations, newScheduler, pct, type SimJob } from "../scripts/cyrus/queue-sim";

const req = createRequire(__filename);
const SCH = req(path.join(__dirname, "../services/modbuilder/scheduler.js"));
const CAP = req(path.join(__dirname, "../services/modbuilder/capacity.js"));

const waits = (r: ReturnType<typeof simulate>, p: string) => r.starts.filter((s) => s.priority === p).map((s) => s.waitSec);

describe("capacity: classes and accounts", () => {
  it("classifies by the request field, then the eval id / account prefix, else interactive (old portals unchanged)", () => {
    assert.deepEqual(SCH.classify({ priority: "batch" }, "mbabc123"), { priority: "batch", source: "request" });
    assert.deepEqual(SCH.classify({ priority: "SYSTEM" }, "mbabc123"), { priority: "system", source: "request" });
    assert.ok(SCH.classify({ priority: "urgent" }, "mbabc123").error);
    assert.equal(SCH.classify({}, "ev-second1-3c22e63e7029").priority, "batch");
    assert.equal(SCH.classify({}, "eval-x-123456").priority, "batch");
    assert.equal(SCH.classify({}, "mine-2026-10-14").priority, "batch");
    assert.equal(SCH.classify({ account: "eval:first1" }, "abcdef12").priority, "batch");
    assert.deepEqual(SCH.classify({}, "mb0123456789abcdef0123"), { priority: "interactive", source: "default" });
    assert.equal(SCH.classify({}, "evil-build-1").priority, "interactive", "only the ev- / eval- prefixes, not any 'ev'");
  });
  it("uses an opaque account key, one shared bucket per class without one", () => {
    assert.equal(SCH.accountOf({ account: "u:5f2a9c" }, "interactive"), "u:5f2a9c");
    assert.equal(SCH.accountOf({}, "interactive"), "anon");
    assert.equal(SCH.accountOf({}, "batch"), "batch");
    assert.equal(SCH.accountOf({ account: "has space" }, "interactive"), "anon");
  });
  it("clamps the reserve to concurrency - 1 and reports what was wanted", () => {
    assert.deepEqual(SCH.schedulerConfig({}, 2), { enabled: true, concurrency: 2, reserve: 1, reserveWanted: 1, starveMs: 1_800_000 });
    const one = SCH.schedulerConfig({}, 1);
    assert.equal(one.reserve, 0);
    assert.equal(one.reserveWanted, 1);
    assert.equal(SCH.schedulerConfig({ MB_RESERVE_INTERACTIVE: "2" }, 4).reserve, 2);
    assert.equal(SCH.schedulerConfig({ MB_PRIORITY: "off" }, 2).enabled, false);
  });
});

describe("capacity: scheduler rules", () => {
  const run = (id: string, priority: string, account: string, startedAt = 0) => ({ id, priority, account, startedAt });
  it("batch never takes the last interactive slot", () => {
    const S = newScheduler({ concurrency: 2 });
    for (let i = 0; i < 3; i++) S.enqueue({ id: `ev-${i}`, priority: "batch", account: "eval:x", at: i });
    const first = S.pick([], 10);
    assert.equal(first?.id, "ev-0");
    assert.equal(S.pick([run("ev-0", "batch", "eval:x")], 10), null, "the second slot is reserved");
    S.enqueue({ id: "mb-user", priority: "interactive", account: "u1", at: 20 });
    assert.equal(S.pick([run("ev-0", "batch", "eval:x")], 20)?.id, "mb-user", "an interactive build takes the reserved slot at once");
  });
  it("interactive is ahead of batch, system ahead of both; FIFO inside a class and account", () => {
    const S = newScheduler({ concurrency: 4 });
    S.enqueue({ id: "ev-1", priority: "batch", account: "eval:x", at: 0 });
    S.enqueue({ id: "u-1", priority: "interactive", account: "u", at: 1 });
    S.enqueue({ id: "u-2", priority: "interactive", account: "u", at: 2 });
    S.enqueue({ id: "sys", priority: "system", account: "anon", at: 3 });
    assert.deepEqual(S.order([], 5).map((x) => x.id), ["sys", "u-1", "u-2", "ev-1"]);
  });
  it("fair share: a burst from three accounts starts round robin, not account by account", () => {
    const jobs: SimJob[] = [];
    for (const a of ["a", "b", "c"]) for (let k = 0; k < 5; k++) jobs.push({ id: `${a}${k}`, account: a, priority: "interactive", arriveSec: 0, durSec: 100 });
    const r = simulate(jobs, { concurrency: 2 });
    assert.deepEqual(r.starts.map((s) => s.account).join(""), "abcabcabcabcabc");
  });
  it("MB_PRIORITY=off is plain FIFO with no reservation (the behaviour before this change)", () => {
    const r = simulate(launchScenario(), { concurrency: 2, env: { MB_PRIORITY: "off" } });
    const order = r.starts.map((s) => s.id);
    assert.deepEqual(order.slice(0, 10), Array.from({ length: 10 }, (_, i) => `ev-sim-${i}`));
    assert.equal(r.maxBatchRunning, 2);
  });
  it("starvation guard: an aged batch build ranks ahead of new interactive work (on a non-reserved slot only)", () => {
    const S = newScheduler({ concurrency: 2, env: { MB_BATCH_STARVE_MIN: "10" } });
    S.enqueue({ id: "ev-old", priority: "batch", account: "eval:x", at: 0 });
    S.enqueue({ id: "u-new", priority: "interactive", account: "u", at: 11 * 60_000 });
    assert.deepEqual(S.order([], 11 * 60_000).map((x) => x.id), ["ev-old", "u-new"]);
    assert.deepEqual(S.order([], 5 * 60_000).map((x) => x.id), ["u-new", "ev-old"], "not aged yet: interactive first");
    // a batch build already holds the only non-reserved slot: the aged one waits, the user still gets the reserved slot
    assert.equal(S.pick([run("ev-run", "batch", "eval:x")], 11 * 60_000)?.id, "u-new");
  });
  it("skips builds waiting for an AI retry and whatever the breaker predicate holds back, never drops them", () => {
    const S = newScheduler({ concurrency: 2 });
    S.enqueue({ id: "u-ai", priority: "interactive", account: "u", at: 0 });
    S.enqueue({ id: "u-bank", priority: "interactive", account: "v", at: 1 });
    const it = S.pick([], 2, (x: { id: string }) => x.id !== "u-ai");
    assert.equal(it?.id, "u-bank");
    assert.equal(S.size(), 1);
    S.requeue({ ...S.list()[0] }, 10_000);
    assert.equal(S.pick([], 5_000), null, "retry time not reached");
    assert.equal(S.pick([], 10_000)?.id, "u-ai");
  });
  it("positions are the real start order, and the estimate is exact when every build takes the same time", () => {
    const jobs: SimJob[] = [];
    for (let i = 0; i < 4; i++) jobs.push({ id: `ev-${i}`, account: "eval:x", priority: "batch", arriveSec: 0, durSec: 120 });
    for (const a of ["a", "b"]) for (let k = 0; k < 3; k++) jobs.push({ id: `${a}${k}`, account: a, priority: "interactive", arriveSec: 0, durSec: 120 });
    // snapshot: all queued at t=0, nothing running yet
    const S = newScheduler({ concurrency: 2 });
    for (const j of jobs) S.enqueue({ id: j.id, priority: j.priority, account: j.account, at: 0 });
    const predicted = S.order([], 0).map((x) => x.id);
    const est = new Map(jobs.map((j) => [j.id, S.estimate(j.id, [], 0, 120_000)]));
    const positions = new Map(jobs.map((j) => [j.id, S.position(j.id, [], 0)]));
    const r = simulate(jobs, { concurrency: 2 });
    assert.deepEqual(r.starts.map((s) => s.id), predicted, "queue positions = actual start order");
    for (const s of r.starts) {
      assert.equal(positions.get(s.id), predicted.indexOf(s.id) + 1);
      assert.equal(est.get(s.id), s.startSec * 1000, `estimate for ${s.id}`);
    }
  });
  it("no estimate without a duration (no samples = no ETA)", () => {
    const S = newScheduler({ concurrency: 2 });
    S.enqueue({ id: "u", priority: "interactive", account: "u", at: 0 });
    assert.equal(S.estimate("u", [], 0, 0), null);
    assert.equal(S.estimate("missing", [], 0, 1000), null);
  });
});

describe("capacity: LOAD TEST 3 accounts x 5 builds + 10 batch builds (fake clock, real scheduler)", () => {
  const prio = simulate(launchScenario(), { concurrency: 2 });
  const fifo = simulate(launchScenario(), { concurrency: 2, env: { MB_PRIORITY: "off" } });
  const maxDur = Math.max(...launchScenario().map((j) => j.durSec));

  it("every build runs exactly once", () => {
    assert.equal(prio.starts.length, 25);
    assert.equal(new Set(prio.starts.map((s) => s.id)).size, 25);
  });
  it("reservation holds: never more than concurrency - reserve batch builds at once", () => {
    assert.equal(prio.maxBatchRunning, 1);
    // at every start, check the running set directly
    for (const s of prio.starts) {
      const atStart = prio.starts.filter((o) => o.priority === "batch" && o.startSec <= s.startSec && o.endSec > s.startSec);
      assert.ok(atStart.length <= 1, `batch running at ${s.startSec}: ${atStart.map((o) => o.id)}`);
    }
  });
  it("interactive wait is bounded: each account's first build waits at most one build's run time, never behind the eval run", () => {
    for (const a of ["acct-a", "acct-b", "acct-c"]) {
      const first = prio.starts.find((s) => s.id === `${a}-0`)!;
