    assert.equal(b.trip(1500, "again"), 3500, "second trip doubles");
    assert.equal(b.trip(3500, "again"), 7500, "capped at maxMs");
    b.success();
    assert.equal(b.state(3600), "closed");
    assert.equal(b.allow(3600), true);
    b.trip(0, "x"); b.allow(2000); b.release();
    assert.equal(b.allow(2001), true, "a probe that ended without an answer frees the slot for another");
  });
});

