    fs.writeFileSync(path.join(cp, "1.21.11.classes.txt"), "org/bukkit/plugin/java/JavaPlugin.class\n");
    const nodePath = path.join(dir, "node_modules");
    try { require.resolve("yaml", { paths: [SVC] }); } catch { fs.mkdirSync(path.join(nodePath, "yaml"), { recursive: true }); fs.writeFileSync(path.join(nodePath, "yaml", "index.js"), YAML_STUB); }
    port = 39000 + Math.floor(Math.random() * 2000);
    proc = spawn(process.execPath, [path.join(SVC, "server.js")], {
      env: {
        PATH: `${bin}:${process.env.PATH}`, HOME: dir, PORT: String(port), MB_DATA: path.join(dir, "data"), MB_WORK: path.join(dir, "work"),
        MB_TEMPLATE: path.join(SVC, "template"), MB_CP_DIR: cp, MODBUILDER_API_KEY: KEY, MB_VERSIONS: "1.21.11", MB_GUARD: "off", NODE_PATH: nodePath,
        MB_CONCURRENCY: "2", MB_ACCOUNT_MAX_ACTIVE: "2", MB_QUEUE_MAX_BATCH: "3", MB_AI_BACKOFF_S: "5", MB_AI_RETRIES: "2",
      } as unknown as NodeJS.ProcessEnv,
      stdio: ["ignore", "ignore", "pipe"],
    });
    proc.stderr?.on("data", (d) => { svcErr += d; });
    for (let i = 0; i < 100; i++) {
      try { if ((await health()).ok) return; } catch { /* starting */ }
      await sleep(100);
    }
    throw new Error(`service did not start: ${svcErr.slice(-2000)}`);
  });
  after(() => { if (proc) proc.kill("SIGKILL"); fs.rmSync(dir, { recursive: true, force: true }); });

  it("/health reports the capacity block with the safe defaults", async () => {
    const h = await health();
    assert.equal(h.features.capacity, true);
    assert.equal(h.features.priorities, true);
    assert.equal(h.concurrency, 2);
    assert.equal(h.capacity.reserveInteractive, 1);
    assert.equal(h.capacity.batchCap, 1);
    assert.equal(h.capacity.accountMaxActive, 2);
    assert.equal(h.capacity.breaker.state, "closed");
    assert.ok(h.capacity.suggestedConcurrency >= 1);
    assert.deepEqual(h.capacity.runSec, { p50: null, p80: null, samples: 0 }, "no samples yet = no estimate");
  });

  it("eval builds are batch by id prefix, take one slot, and a portal build still starts at once (reserved slot)", async () => {
    for (let i = 0; i < 3; i++) assert.equal((await api("POST", "/builds", { id: `ev-cap-${i}x`, prompt: P(`SLEEPMS=2500 b${i}`), mcVersion: "1.21.11" })).status, 202);
    const b1 = (await api("GET", "/builds/ev-cap-1x")).j;
    assert.equal(b1.priority, "batch");
    assert.equal(b1.priorityFrom, "id-prefix");
    assert.equal(b1.status, "queued", "batch may not take the reserved slot");
    assert.equal(b1.queuePosition, 1);
    assert.equal(b1.queue.position, 1);
    assert.equal(b1.queue.state, "next");
    assert.equal(b1.queue.waitSec.p50, null, "no fake ETA before 5 finished builds");
    assert.equal(b1.account, undefined, "the account key is never shown");
    const u = await api("POST", "/builds", { id: "mbcapuser01", prompt: P("SLEEPMS=300 u1"), mcVersion: "1.21.11", account: "u:aaaa", priority: "interactive" });
    assert.equal(u.status, 202);
    assert.notEqual(u.j.status, "queued", "started right away despite two eval builds waiting");
    const h = await health();
    assert.equal(h.capacity.running.batch, 1);
    assert.equal(h.capacity.running.interactive, 1);
    assert.equal(h.capacity.queued.batch, 2);
    await waitFor("mbcapuser01", done);
  });

  it("the batch line is bounded (MB_QUEUE_MAX_BATCH): a clear retryable 503", async () => {
    assert.equal((await api("POST", "/builds", { id: "ev-cap-3x", prompt: P("SLEEPMS=10 b3"), mcVersion: "1.21.11" })).status, 202);
    const r = await api("POST", "/builds", { id: "ev-cap-4x", prompt: P("SLEEPMS=10 b4"), mcVersion: "1.21.11" });
    assert.equal(r.status, 503);
    assert.equal(r.j.code, "capacity");
    assert.equal(r.j.retryable, true);
    assert.ok(r.j.retryAfterSec >= 30);
    assert.equal((await api("GET", "/builds/ev-cap-4x")).status, 404, "nothing stored for a refused build");
    for (let i = 0; i < 4; i++) await waitFor(`ev-cap-${i}x`, done);
  });

  it("per-account cap (MB_ACCOUNT_MAX_ACTIVE): the third active build of one account is refused, retryable, others unaffected", async () => {
    assert.equal((await api("POST", "/builds", { id: "mbcapacct01", prompt: P("SLEEPMS=1500 a1"), mcVersion: "1.21.11", account: "u:bbbb" })).status, 202);
    assert.equal((await api("POST", "/builds", { id: "mbcapacct02", prompt: P("SLEEPMS=1500 a2"), mcVersion: "1.21.11", account: "u:bbbb" })).status, 202);
    const third = await api("POST", "/builds", { id: "mbcapacct03", prompt: P("SLEEPMS=10 a3"), mcVersion: "1.21.11", account: "u:bbbb" });
    assert.equal(third.status, 429);
    assert.equal(third.j.code, "account_busy");
    assert.equal(third.j.retryable, true);
    assert.equal((await api("POST", "/builds", { id: "mbcapother1", prompt: P("SLEEPMS=10 o1"), mcVersion: "1.21.11", account: "u:cccc" })).status, 202);
    assert.equal((await api("POST", "/builds", { id: "mbcapbad001", prompt: P("x"), mcVersion: "1.21.11", priority: "urgent" })).status, 400);
    for (const id of ["mbcapacct01", "mbcapacct02", "mbcapother1"]) await waitFor(id, done);
  });

  it("an AI session limit does not fail the build: it waits in line, retries by itself, and the lost attempt is not charged", async () => {
    assert.equal((await api("POST", "/builds", { id: "mbcaplimit1", prompt: P("LIMITHITone"), mcVersion: "1.21.11", account: "u:dddd" })).status, 202);
    const waiting = await waitFor("mbcaplimit1", (j) => j.status === "queued" && j.queue?.state === "ai_wait");
    assert.equal(waiting.aiRetries, 1);
    assert.ok(waiting.queue.retryAt);
    assert.ok(waiting.events.some((e: { message: string }) => /The AI is busy right now\. Cyrus will try again automatically/.test(e.message)));
    const h = await health();
    assert.equal(h.capacity.breaker.state, "open");
    assert.equal(h.capacity.breaker.trips, 1);
    // a non-AI request is not held by the breaker; an AI build waits behind it instead of failing
    assert.equal((await api("POST", "/builds", { id: "mbcapafter1", prompt: P("SLEEPMS=10 after"), mcVersion: "1.21.11", account: "u:eeee" })).status, 202);
    const after1 = (await api("GET", "/builds/mbcapafter1")).j;
    assert.equal(after1.status, "queued");
    assert.equal(after1.queue.state, "ai_wait");
    const fin = await waitFor("mbcaplimit1", done, 40_000);
    assert.equal(fin.status, "succeeded", JSON.stringify(fin.events?.map((e: { message: string }) => e.message)));
    assert.equal(fin.costUsd, 0.05, "only the attempt that worked");
    assert.equal(fin.lostCostUsd, 0.01, "the limited attempt is recorded aside");
    assert.equal((await waitFor("mbcapafter1", done, 40_000)).status, "succeeded");
    assert.equal((await health()).capacity.breaker.state, "closed");
  });

  it("estimates appear once enough builds finished, as p50 <= p80 seconds", async () => {
    const h = await health();
    assert.ok(h.capacity.runSec.samples >= 5, JSON.stringify(h.capacity.runSec));
    assert.ok(h.capacity.waitSec.samples >= 5);
    // two long builds fill both slots; the third waits with an estimate
    for (const [id, acct] of [["mbcapest001", "u:f1"], ["mbcapest002", "u:f2"], ["mbcapest003", "u:f3"]]) assert.equal((await api("POST", "/builds", { id, prompt: P(`SLEEPMS=1200 ${id}`), mcVersion: "1.21.11", account: acct })).status, 202);
    const q = (await api("GET", "/builds/mbcapest003")).j;
    assert.equal(q.status, "queued");
    assert.equal(q.queue.position, 1);
    assert.ok(q.queue.waitSec.p50 !== null && q.queue.waitSec.p80 !== null && q.queue.waitSec.p50 <= q.queue.waitSec.p80, JSON.stringify(q.queue));
    for (const id of ["mbcapest001", "mbcapest002", "mbcapest003"]) await waitFor(id, done);
  });
});

