// Cyrus capacity, scale-out readiness: the portal-side DISPATCHER for N build workers. PURE (fetching is injected), unit-tested
// with fakes in test/cyrus-capacity-portal.test.ts. Off by default: one worker (MODBUILDER_URL), exactly as before.
//
//   CYRUS_MB_DISPATCH=1 + MODBUILDER_URLS=http://127.0.0.1:7340,http://127.0.0.1:7341  (comma or space separated; every
//   worker takes the same MODBUILDER_API_KEY). Fewer than two URLs = single-worker mode.
//
// Design (docs/cyrus/07-operations.md "Scale-out: more build workers"):
//   - stateless: the portal keeps no table of workers' builds; build ids are global (mb + 20 hex), so a build is found by
//     asking. A sticky in-memory map (id -> worker) answers the hot path; on a miss (restart, other web process) the
//     dispatcher asks each worker GET /builds/<id> once and remembers the one that has it.
//   - placement by load: a NEW build goes to the healthy worker with the lowest (running + queued) / concurrency that
//     serves its Minecraft version, skipping workers whose AI circuit breaker is open; ties go to the first listed.
//   - change builds are sticky to the CHAIN: a change (baseBuildId) must run where the base build's workspace lives, so it
//     goes to the base build's worker, whatever the load.
//   - /health answers are cached for a few seconds per worker (a dead worker costs one short timeout per period).

export type Worker = { url: string; key: string };
export type WorkerHealth = {
  ok?: boolean; running?: number; queued?: number; concurrency?: number; versions?: string[];
  capacity?: { breaker?: { state?: string } | null; queued?: Record<string, number>; running?: Record<string, number> } | null;
  [k: string]: unknown;
};

const ON = new Set(["1", "true", "on", "yes"]);

/** The worker list when dispatch is ON and at least two URLs are set; null = single-worker mode (the default). */
export function dispatchWorkers(env: Record<string, string | undefined>, key: string): Worker[] | null {
  if (!ON.has(String(env.CYRUS_MB_DISPATCH || "").toLowerCase())) return null;
  const urls = [...new Set(String(env.MODBUILDER_URLS || "").split(/[\s,]+/).map((u) => u.trim().replace(/\/+$/, "")).filter((u) => /^https?:\/\/[^\s/]+/.test(u)))];
  if (urls.length < 2 || !key) return null;
  return urls.map((url) => ({ url, key }));
}

/** Load of one worker (lower is better); null = do not place new builds there. */
export function loadScore(h: WorkerHealth | null, mcVersion?: string): number | null {
  if (!h || h.ok !== true) return null;
  if (mcVersion && Array.isArray(h.versions) && h.versions.length && !h.versions.includes(mcVersion)) return null;
  const c = Math.max(1, Number(h.concurrency) || 1);
  const load = ((Number(h.running) || 0) + (Number(h.queued) || 0)) / c;
  const open = h.capacity?.breaker?.state === "open";
  return open ? 1000 + load : load;
}

export function chooseWorker(cands: { w: Worker; health: WorkerHealth | null }[], mcVersion?: string): Worker | null {
  let best: { w: Worker; s: number } | null = null;
  for (const c of cands) {
    const s = loadScore(c.health, mcVersion);
    if (s === null) continue;
    if (!best || s < best.s) best = { w: c.w, s };
  }
  return best ? best.w : null;
}

export type DispatchDeps = {
  workers: Worker[];
  health(w: Worker): Promise<WorkerHealth | null>;
  /** does this worker know the build (GET /builds/<id> answered 200)? */
  has(w: Worker, id: string): Promise<boolean>;
  now?: () => number;
  healthTtlMs?: number;
  maxSticky?: number;
};

export function createDispatcher(d: DispatchDeps) {
  const now = d.now ?? Date.now;
  const ttl = d.healthTtlMs ?? 5000;
  const max = d.maxSticky ?? 5000;
  const sticky = new Map<string, Worker>();
  const hc = new Map<string, { at: number; v: WorkerHealth | null }>();
  const health = async (w: Worker) => {
    const c = hc.get(w.url);
    if (c && now() - c.at < ttl) return c.v;
    const v = await d.health(w).catch(() => null);
    hc.set(w.url, { at: now(), v });
    return v;
  };
  const remember = (id: string, w: Worker) => {
    sticky.delete(id);
    sticky.set(id, w);
    if (sticky.size > max) sticky.delete(sticky.keys().next().value as string);
  };
  return {
    remember,
    forget: (id: string) => sticky.delete(id),
    known: (id: string) => sticky.get(id) ?? null,
    /** All workers with their (cached) health, for the admin Live tab. */
    async all(): Promise<{ w: Worker; health: WorkerHealth | null }[]> {
      return Promise.all(d.workers.map(async (w) => ({ w, health: await health(w) })));
    },
    /** Where a NEW build goes: the least-loaded healthy worker for this version; the first worker when none answers. */
    async pick(mcVersion?: string): Promise<Worker> {
      return chooseWorker(await this.all(), mcVersion) ?? d.workers[0];
    },
    /** Where an existing build lives (sticky, then ask each worker once). null = nobody has it. */
    async workerFor(id: string): Promise<Worker | null> {
      const s = sticky.get(id);
      if (s) return s;
      for (const w of d.workers) {
        if (await d.has(w, id).catch(() => false)) { remember(id, w); return w; }
      }
      return null;
    },
    /** A new build's worker: a change follows its base build; anything else by load. */
    async place(id: string, opts: { baseBuildId?: string | null; mcVersion?: string }): Promise<Worker> {
      const w = (opts.baseBuildId ? await this.workerFor(opts.baseBuildId) : null) ?? (await this.pick(opts.mcVersion));
      remember(id, w);
      return w;
    },
  };
}
export type Dispatcher = ReturnType<typeof createDispatcher>;

