export async function svcCancel(id: string): Promise<void> {
  await call(`/builds/${encodeURIComponent(id)}/cancel`, { method: "POST" });
}

export async function svcArtifact(id: string): Promise<Buffer> {
  const r = await call(`/builds/${encodeURIComponent(id)}/artifact`, { timeoutMs: 60_000 });
  if (!r.ok) throw new Error(`artifact fetch failed (${r.status})`);
  return Buffer.from(await r.arrayBuffer());
}

export async function svcSource(id: string, path: string): Promise<Response> {
  return call(`/builds/${encodeURIComponent(id)}/source?path=${encodeURIComponent(path)}`);
}

/** Live view of a running build (service 0.4+): src/main/** files + the file being written right now. */
export type SvcLive = {
  live: boolean;
  status: string;
  files: { path: string; size: number; hash: string }[];
  draft: { path: string; op: "write" | "edit"; seq: number; from: number; text: string; total: number; done: boolean } | null;
  /** Cyrus r48: only when asked (`assets`) and the service runs with CYRUS_LIVE_ASSETS=1. */
  assets?: SvcLiveAssets;
};
export type SvcLiveAssets = {
  seq: number;
  events: Record<string, unknown>[];
  gap?: boolean;
  stored?: boolean;
  draft: { kind: string; path: string; op: "write" | "edit"; seq: number; from: number; text: string; total: number; done: boolean; truncated?: boolean } | null;
};
/** Cyrus r48 live assets query: events after `aseq`, and the asset draft being followed (path + tool-call seq + from). */
export type SvcLiveAssetsQuery = { aseq: number; adraft?: string; aseqd?: number; afrom?: number };

export async function svcLive(id: string, draft?: string, from?: number, seq?: number, assets?: SvcLiveAssetsQuery): Promise<SvcLive | null> {
  const n = (x: number | undefined) => Math.max(0, Math.floor(x ?? 0));
  const parts = draft ? [`draft=${encodeURIComponent(draft)}`, `seq=${n(seq)}`, `from=${n(from)}`] : [];
  if (assets) {
    parts.push("assets=1", `aseq=${n(assets.aseq)}`);
    if (assets.adraft) parts.push(`adraft=${encodeURIComponent(assets.adraft)}`, `aseqd=${n(assets.aseqd)}`, `afrom=${n(assets.afrom)}`);
  }
  const q = parts.length ? `?${parts.join("&")}` : "";
  const r = await call(`/builds/${encodeURIComponent(id)}/live${q}`, { timeoutMs: 8000 });
  // An older service image has no /live: treat as "nothing live" rather than an error.
  if (r.status === 404) return null;
  if (!r.ok) throw new ModBuilderUnavailable(`service returned ${r.status}`);
  return (await r.json()) as SvcLive;
}

export async function svcSourceZip(id: string): Promise<Response> {
  return call(`/builds/${encodeURIComponent(id)}/source.zip`, { timeoutMs: 60_000 });
}

/**
 * Cyrus import (service with features.imports): hand the VETTED files of an import to the build service. `source` makes
 * a base build (no AI; javac + allowlisted compile-only jars + attested scan); `jar` is analysis only. The service checks
 * everything again. Large: the body carries the files as base64 (portal caps the upload at 25 MB).
 */
export type SvcImportBody = {
  id: string; mcVersion: string; kind: "source" | "jar"; pluginName?: string; namespace: string;
  files: { path: string; data: string }[]; docs?: { path: string; text: string }[]; deps?: string[];
};
export async function svcImport(body: SvcImportBody): Promise<ServiceBuild> {
  const r = await call("/imports", { method: "POST", body: JSON.stringify(body), timeoutMs: 120_000 });
  const j = await r.json().catch(() => ({}));
  if (r.status !== 202) throw new Error((j as { error?: string }).error || `service returned ${r.status}`);
  return j as ServiceBuild;
}

/**
 * Cyrus live-test fix (F): the mod planner on the build service (POST /plan, image 0.6+ with features.planner). Raw model
 * text; lib/cyrus/planner/lanes.ts parsePlannerText validates it. Throws on any transport problem (the caller falls back).
 */
export async function svcPlan(body: { text: string; game: string; mcVersion: string }, timeoutMs = 9000): Promise<{ text: string | null; costUsd: number; ms: number }> {
  const r = await call("/plan", { method: "POST", body: JSON.stringify(body), timeoutMs });
  if (!r.ok) throw new ModBuilderUnavailable(`planner returned ${r.status}`);
  const j = (await r.json().catch(() => ({}))) as { text?: unknown; costUsd?: unknown; ms?: unknown };
  return { text: typeof j.text === "string" ? j.text : null, costUsd: typeof j.costUsd === "number" ? j.costUsd : 0, ms: typeof j.ms === "number" ? j.ms : 0 };
}

/** Cyrus prompt coach: the one-call "Rewrite for me" (service features.coach). Raw text; the caller validates it. */
export async function svcCoach(body: { text: string; draft: string; mcVersion: string; change?: { name: string } | null }, timeoutMs = 20000): Promise<{ text: string | null; costUsd: number; ms: number }> {
  const r = await call("/coach", { method: "POST", body: JSON.stringify(body), timeoutMs });
  if (!r.ok) throw new ModBuilderUnavailable(`coach returned ${r.status}`);
  const j = (await r.json().catch(() => ({}))) as { text?: unknown; costUsd?: unknown; ms?: unknown };
  return { text: typeof j.text === "string" ? j.text : null, costUsd: typeof j.costUsd === "number" ? j.costUsd : 0, ms: typeof j.ms === "number" ? j.ms : 0 };
}
