// Cyrus capacity: what the plan and build screens SAY about the queue. PURE + client-safe, unit-tested in
// test/cyrus-capacity-portal.test.ts. Truthful by construction: every number comes from the build service (place in line,
// p50/p80 of its recent run times); with no measurement there is no ETA, only the place in line. Never names a model.
import type { MbQueue } from "./types";
import type { SvcQueue } from "./client";

const num = (v: unknown): number | null => (typeof v === "number" && Number.isFinite(v) && v >= 0 ? Math.round(v) : null);

/** Keep only the facts the customer view needs (the service record has more). */
export function queueFacts(q: SvcQueue): MbQueue {
  const state = q.state === "next" || q.state === "ai_wait" ? q.state : "waiting";
  return {
    position: num(q.position) ?? 0, ahead: num(q.ahead) ?? 0, state,
    waitSec: { p50: num(q.waitSec?.p50), p80: num(q.waitSec?.p80) },
    retryAt: typeof q.retryAt === "string" && !Number.isNaN(Date.parse(q.retryAt)) ? q.retryAt : null,
  };
}

/** "under a minute" / "about 4 min" / "about 3–6 min" (rounded to whole minutes; p80 never below p50). */
export function waitPhrase(p50: number | null, p80: number | null): string | null {
  if (p50 === null) return null;
  if (p50 < 60 && (p80 === null || p80 < 60)) return "under a minute";
  const a = Math.max(1, Math.round(p50 / 60));
  const b = p80 === null ? a : Math.max(a, Math.round(p80 / 60));
  return a === b ? `about ${a} min` : `about ${a}–${b} min`;
}

const NOTHING_SPENT = "Nothing is spent until it starts.";

/** The label + one plain sentence for a QUEUED build. `queue` absent (older build service) = place in line only. */
export function queueLine(r: { queuePosition?: number; queue?: MbQueue | null } | null | undefined, nowMs = Date.now()): { label: string; detail: string; state: "next" | "waiting" | "ai_wait" | "unknown" } {
  const q = r?.queue ?? null;
  if (!q) {
    const pos = r?.queuePosition || 0;
    return { label: "Waiting for a free builder", detail: pos > 1 ? `In line, position ${pos}. ${NOTHING_SPENT}` : NOTHING_SPENT, state: "unknown" };
  }
  if (q.state === "ai_wait") {
    const mins = q.retryAt ? Math.max(1, Math.round((Date.parse(q.retryAt) - nowMs) / 60000)) : null;
    return { label: "Waiting for the AI", detail: `The AI is busy right now. Cyrus will try again by itself${mins ? ` in about ${mins} min` : " shortly"}; you do not need to do anything. Nothing is charged for the wait.`, state: "ai_wait" };
  }
  const wait = waitPhrase(q.waitSec.p50, q.waitSec.p80);
  if (q.state === "next") {
    const soon = q.waitSec.p50 !== null && q.waitSec.p50 <= 90;
    return { label: soon ? "Starting soon" : "Next in line", detail: `${soon ? "It starts as soon as a builder frees up" : `Next for a free builder${wait ? `, usually ${wait}` : ""}`}. ${NOTHING_SPENT}`, state: "next" };
  }
  const ahead = q.ahead === 1 ? "1 build is" : `${q.ahead} builds are`;
  return { label: "Waiting for a free builder", detail: `${ahead} ahead of yours${wait ? `; usually ${wait} until it starts` : ""}. ${NOTHING_SPENT}`, state: "waiting" };
}

/** Plan screen (CYRUS_CAPACITY_UI): the builder's state right now, from /health capacity. null = say nothing. */
export type PlanCapacity = { state: "free" | "busy" | "ai_busy"; ahead: number; waitSec: { p50: number | null; p80: number | null } };

type HealthCap = { running?: Record<string, number>; queued?: Record<string, number>; concurrency?: number; runSec?: { p50?: number | null; p80?: number | null }; breaker?: { state?: string } };

/**
 * A new interactive build's outlook from the service's own numbers: builds of its class (and system) ahead of it, free
 * slots, and the measured run time. The wait is an approximation (waves of `concurrency` builds, the current wave half
 * done), labelled "usually about" on screen; with no measured run time there is no number.
 */
export function planCapacity(health: { concurrency?: number; capacity?: HealthCap | null } | null | undefined): PlanCapacity | null {
  const c = health?.capacity;
  if (!c || !c.running || !c.queued) return null;
  const conc = Math.max(1, Number(c.concurrency ?? health?.concurrency) || 1);
  const running = Object.values(c.running).reduce((a, b) => a + (Number(b) || 0), 0);
  const ahead = (Number(c.queued.system) || 0) + (Number(c.queued.interactive) || 0);
  if (c.breaker?.state === "open") return { state: "ai_busy", ahead, waitSec: { p50: null, p80: null } };
  const free = Math.max(0, conc - running);
  if (free > ahead) return { state: "free", ahead: 0, waitSec: { p50: 0, p80: 0 } };
  const waves = Math.ceil((ahead + 1 - free) / conc);
  const est = (p: number | null | undefined) => (typeof p === "number" && p > 0 ? Math.round((waves - 0.5) * p) : null);
  return { state: "busy", ahead, waitSec: { p50: est(c.runSec?.p50), p80: est(c.runSec?.p80) } };
}

export function planCapacityLine(p: PlanCapacity | null): string | null {
  if (!p) return null;
  if (p.state === "free") return "A builder is free: it starts right away.";
  if (p.state === "ai_busy") return "The AI is busy right now. Your build waits in line and starts by itself; nothing is charged for the wait.";
  const wait = waitPhrase(p.waitSec.p50, p.waitSec.p80);
  return `${p.ahead === 0 ? "Next for a free builder" : `${p.ahead} ${p.ahead === 1 ? "build" : "builds"} ahead of yours`}${wait ? `, usually ${wait} before it starts` : ""}.`;
}

