import type { WorkerHealth } from "./dispatch";

export const CAPACITY_SETTING_DEFAULTS = {
  /** Builds one account may have waiting or running at once (the old MAX_INFLIGHT). PLACEHOLDER pending the owner. */
  cyrus_capacity_account_max_active: "2",
  /** Admin alert (Live tab) when this many builds wait in line across all builders. 0 = off. PLACEHOLDER. */
  cyrus_capacity_alert_queue_depth: "6",
  /** Admin alert when the p80 time in line of recent builds passes this many minutes. 0 = off. PLACEHOLDER. */
  cyrus_capacity_alert_wait_p80_min: "10",
} as const;
export type CapacitySettingKey = keyof typeof CAPACITY_SETTING_DEFAULTS;
export const CAPACITY_SETTING_KEYS = Object.keys(CAPACITY_SETTING_DEFAULTS) as CapacitySettingKey[];

/** Codes on a refused/failed create (all retryable, nothing charged). */
export const RATE_LIMITED = "rate_limited";
export const ACCOUNT_BUSY = "account_busy";
export const CAPACITY = "capacity";

type Cap = {
  running?: Record<string, number>; queued?: Record<string, number>; waitingForAi?: number; oldestQueuedSec?: number | null;
  runSec?: { p50: number | null; p80: number | null; samples: number }; waitSec?: { p50: number | null; p80: number | null; samples: number };
  breaker?: { state: string; until: string | null; trips: number; reason?: string | null };
  reserveInteractive?: number; batchCap?: number; suggestedConcurrency?: number; priority?: boolean; warnings?: string[];
};

export type WorkerRow = {
  label: string; ok: boolean; concurrency: number | null; suggested: number | null; reserve: number | null; priorities: boolean | null;
  running: { system: number; interactive: number; batch: number }; queued: { system: number; interactive: number; batch: number };
  waitingForAi: number; oldestQueuedSec: number | null;
  runSec: { p50: number | null; p80: number | null; samples: number } | null; waitSec: { p50: number | null; p80: number | null; samples: number } | null;
  breaker: { state: string; until: string | null; trips: number } | null; warnings: string[]; capacityKnown: boolean;
};
export type CapacityPanel = {
  workers: WorkerRow[];
  total: { concurrency: number; running: number; queued: number; queuedByClass: { system: number; interactive: number; batch: number }; runningByClass: { system: number; interactive: number; batch: number } };
  alerts: { level: "warn" | "urgent"; text: string }[];
  thresholds: { queueDepth: number; waitP80Min: number };
};

const cls = (o: Record<string, number> | undefined) => ({ system: Number(o?.system) || 0, interactive: Number(o?.interactive) || 0, batch: Number(o?.batch) || 0 });
const sum = (o: { system: number; interactive: number; batch: number }) => o.system + o.interactive + o.batch;

export function workerRow(label: string, h: WorkerHealth | null): WorkerRow {
  const c = (h?.capacity ?? null) as Cap | null;
  const running = c?.running ? cls(c.running) : { system: 0, interactive: Number(h?.running) || 0, batch: 0 };
  const queued = c?.queued ? cls(c.queued) : { system: 0, interactive: Number(h?.queued) || 0, batch: 0 };
  return {
    label, ok: h?.ok === true, concurrency: typeof h?.concurrency === "number" ? h.concurrency : null,
    suggested: typeof c?.suggestedConcurrency === "number" ? c.suggestedConcurrency : null,
    reserve: typeof c?.reserveInteractive === "number" ? c.reserveInteractive : null, priorities: typeof c?.priority === "boolean" ? c.priority : null,
    running, queued, waitingForAi: Number(c?.waitingForAi) || 0, oldestQueuedSec: typeof c?.oldestQueuedSec === "number" ? c.oldestQueuedSec : null,
    runSec: c?.runSec ?? null, waitSec: c?.waitSec ?? null,
    breaker: c?.breaker ? { state: String(c.breaker.state), until: c.breaker.until ?? null, trips: Number(c.breaker.trips) || 0 } : null,
    warnings: Array.isArray(c?.warnings) ? c!.warnings!.map(String).slice(0, 5) : [], capacityKnown: !!c,
  };
}

/** Totals + alerts for the admin Live tab. Thresholds 0 = that alert off. */
export function capacityPanel(workers: { label: string; health: WorkerHealth | null }[], thresholds: { queueDepth: number; waitP80Min: number }): CapacityPanel {
  const rows = workers.map((w) => workerRow(w.label, w.health));
  const z = () => ({ system: 0, interactive: 0, batch: 0 });
  const qc = z(), rc = z();
  for (const r of rows) for (const k of ["system", "interactive", "batch"] as const) { qc[k] += r.queued[k]; rc[k] += r.running[k]; }
  const alerts: CapacityPanel["alerts"] = [];
  for (const r of rows) {
    if (!r.ok) alerts.push({ level: "urgent", text: `${r.label} is not answering /health.` });
    if (r.breaker && r.breaker.state !== "closed") alerts.push({ level: "urgent", text: `${r.label}: the AI backend is rate-limited or busy (breaker ${r.breaker.state}${r.breaker.until ? ` until ${r.breaker.until.slice(11, 16)} UTC` : ""}). Builds wait and retry by themselves.` });
    if (r.waitingForAi > 0) alerts.push({ level: "warn", text: `${r.label}: ${r.waitingForAi} build${r.waitingForAi === 1 ? "" : "s"} waiting for an AI retry.` });
    for (const w of r.warnings) alerts.push({ level: "warn", text: `${r.label}: ${w}` });
    if (r.ok && !r.capacityKnown) alerts.push({ level: "warn", text: `${r.label} runs an image without the capacity queue (no priorities or wait percentiles until the next image).` });
  }
  const queued = sum(qc);
  if (thresholds.queueDepth > 0 && queued >= thresholds.queueDepth) alerts.push({ level: queued >= thresholds.queueDepth * 2 ? "urgent" : "warn", text: `${queued} builds are waiting in line (alert at ${thresholds.queueDepth}).` });
  const p80s = rows.map((r) => r.waitSec?.p80).filter((x): x is number => typeof x === "number");
  const worst = p80s.length ? Math.max(...p80s) : null;
  if (thresholds.waitP80Min > 0 && worst !== null && worst >= thresholds.waitP80Min * 60) alerts.push({ level: "warn", text: `Recent builds waited up to ${Math.round(worst / 60)} min in line at p80 (alert at ${thresholds.waitP80Min} min).` });
  return {
    workers: rows,
    total: { concurrency: rows.reduce((a, r) => a + (r.concurrency || 0), 0), running: sum(rc), queued, queuedByClass: qc, runningByClass: rc },
    alerts, thresholds,
  };
}

