// Cyrus capacity: the SERVER side of the portal's part (settings reads, the fair-share account key, the calm busy failure,
// the admin capacity panel). Pure parts and defaults: ./capacity-pure.ts.
import { createHash } from "node:crypto";
import { getHost } from "../host";
import { svcHealthAll, type ModBuilderBusy } from "./client";
import { ACCOUNT_BUSY, CAPACITY, CAPACITY_SETTING_DEFAULTS, capacityPanel, type CapacityPanel } from "./capacity-pure";

export { RATE_LIMITED, ACCOUNT_BUSY, CAPACITY } from "./capacity-pure";

/** Opaque per-account fair-share key for the build service: never the user id itself. */
export function accountKey(userId: string): string {
  return "u:" + createHash("sha256").update(`cyrus-capacity:${userId}`).digest("hex").slice(0, 16);
}

async function settingInt(key: keyof typeof CAPACITY_SETTING_DEFAULTS, min: number, max: number): Promise<number> {
  const d = Number(CAPACITY_SETTING_DEFAULTS[key]);
  try {
    const v = await getHost().settings.getInt(key, d);
    return Number.isFinite(v) && v >= min && v <= max ? v : d;
  } catch { return d; }
}

/** Builds one account may have waiting or running (cyrus_capacity_account_max_active, default 2; a bad value = default). */
export const accountMaxActive = () => settingInt("cyrus_capacity_account_max_active", 1, 50);

/** The failed row's error for a capacity refusal: plain, calm, retryable; errorCode capacity is never charged. */
export function busyFailure(e: ModBuilderBusy): { errorCode: string; error: string } {
  const wait = e.retryAfterSec ? (e.retryAfterSec < 90 ? "in a minute" : `in about ${Math.round(e.retryAfterSec / 60)} minutes`) : "in a few minutes";
  return e.code === ACCOUNT_BUSY
    ? { errorCode: CAPACITY, error: `You already have builds waiting or running. Nothing was charged; start this one again when one has finished.` }
    : { errorCode: CAPACITY, error: `Every builder is busy right now, so this build did not start. Nothing was charged and your tokens are back. Please try again ${wait}.` };
}

/** Admin Live tab: queue depth, wait percentiles, concurrency, the priority mix and alerts, from every worker's /health. */
export async function loadCapacityPanel(): Promise<CapacityPanel> {
  const [workers, queueDepth, waitP80Min] = await Promise.all([
    svcHealthAll().catch(() => [{ label: "builder", health: null }]),
    settingInt("cyrus_capacity_alert_queue_depth", 0, 10_000),
    settingInt("cyrus_capacity_alert_wait_p80_min", 0, 10_000),
  ]);
  return capacityPanel(workers, { queueDepth, waitP80Min });
}

