content.content:
// Cyrus admin Live tab (2026-10-13): GET -> the feed (last 24 h, newest first) + error groups; GET ?id=<buildId> -> one
// build's full prompt and progress. Same guard as the pages (real account, not impersonating, preview list, fleet area);
// anything else is a plain 404. Opening a build's detail is audited (it shows the whole prompt); the 5 s feed poll is not.
import { cyrusAdminApiUser } from "@/lib/cyrus/admin/gate";
import { cyrusAudit } from "@/lib/cyrus/admin/audit";
import { loadLiveDetail, loadLiveFeed } from "@/lib/cyrus/admin/live-data";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const NO_STORE = { "cache-control": "no-store" };

export async function GET(req: Request) {
  const admin = await cyrusAdminApiUser("live.view");
  if (!admin) return new Response("Not found", { status: 404 });
  const id = new URL(req.url).searchParams.get("id");
  try {
    if (id) {
      const d = await loadLiveDetail(id);
      if (!d) return Response.json({ error: "not_found" }, { status: 404, headers: NO_STORE });
      await cyrusAudit({ actorId: admin.id, action: "live.view", target: `build:${d.id}`, note: "prompt and progress opened in the Live drawer" });
      return Response.json(d, { headers: NO_STORE });
    }
    return Response.json(await loadLiveFeed(), { headers: NO_STORE });
  } catch (e) {
    console.error("[cyrus-admin] live feed failed", (e as Error).message);
    return Response.json({ error: "unavailable" }, { status: 503, headers: NO_STORE });
  }
}
"use client";
// Cyrus admin Live tab: polls /api/admin/cyrus/live every 5 s (no websockets), filters client-side, opens a detail drawer
// for one build and copies a grouped error as a plain-text report. Uses only the admin portal's shared classes so dark and
// light both come from app/admin/admin-shell.css. The feed carries MASKED account labels; the drawer adds the full email
// (the detail call is audited on the server).
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { LIVE_FILTERS, LIVE_POLL_MS, errorReport, filterLive, type ErrorGroup, type LiveDetail, type LiveFilter, type LiveRow } from "@/lib/cyrus/admin/live";
import { Badge } from "@/components/ui/primitives";

type Feed = { at: string; rows: LiveRow[]; groups: ErrorGroup[]; counts: { running: number; failed: number; succeeded: number; total: number } };

const usd = (x: number) => `$${x.toFixed(x < 1 ? 3 : 2)}`;
const secs = (ms: number | null) => (!ms ? "–" : ms < 60_000 ? `${Math.round(ms / 1000)}s` : `${(ms / 60_000).toFixed(1)}m`);
const clock = (iso: string) => iso.slice(11, 19);
const tone = (o: string) => (o === "succeeded" ? "green" : o === "running" ? "brand" : o === "refused" ? "amber" : o === "failed" ? "red" : "slate");

export function LiveFeed({ initial, origin }: { initial: Feed; origin: string }) {
  const [feed, setFeed] = useState<Feed>(initial);
  const [filter, setFilter] = useState<LiveFilter>("all");
  const [paused, setPaused] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [open, setOpen] = useState<string | null>(null);
  const [detail, setDetail] = useState<LiveDetail | null>(null);
  const [detailErr, setDetailErr] = useState<string | null>(null);
  const [copied, setCopied] = useState<string | null>(null);
  const alive = useRef(true);

  const poll = useCallback(async () => {
    try {
      const r = await fetch("/api/admin/cyrus/live", { cache: "no-store" });
      if (!r.ok) throw new Error(String(r.status));
      const j = (await r.json()) as Feed;
      if (alive.current) { setFeed(j); setErr(null); }
    } catch { if (alive.current) setErr("Could not refresh. Retrying every 5 s."); }
  }, []);

  useEffect(() => {
    alive.current = true;
    if (paused) return () => { alive.current = false; };
    const t = setInterval(() => { if (document.visibilityState === "visible") void poll(); }, LIVE_POLL_MS);
    return () => { alive.current = false; clearInterval(t); };
  }, [paused, poll]);

  // the drawer re-reads its build every 5 s while that build is still running
  const openId = open;
  const running = feed.rows.find((r) => r.id === openId)?.outcome === "running";
  useEffect(() => {
    if (!openId) return;
    let stop = false;
    const load = async () => {
      try {
        const r = await fetch(`/api/admin/cyrus/live?id=${encodeURIComponent(openId)}`, { cache: "no-store" });
        if (!r.ok) throw new Error();
        const j = (await r.json()) as LiveDetail;
        if (!stop) { setDetail(j); setDetailErr(null); }
      } catch { if (!stop) setDetailErr("Could not load this build."); }
    };
    setDetail(null); setDetailErr(null);
    void load();
    const t = running ? setInterval(load, LIVE_POLL_MS) : null;
    return () => { stop = true; if (t) clearInterval(t); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [openId, running]);

  const now = new Date(feed.at);
  const rows = useMemo(() => filterLive(feed.rows, filter, now), [feed, filter]); // eslint-disable-line react-hooks/exhaustive-deps
  const copy = async (key: string, text: string) => {
    try { await navigator.clipboard.writeText(text); setCopied(key); setTimeout(() => setCopied((c) => (c === key ? null : c)), 2000); } catch { setCopied(null); }
  };

  return (
    <div>
      <div className="mb-4 flex flex-wrap items-center gap-2" role="group" aria-label="Filter">
        {LIVE_FILTERS.map((f) => (
          <button key={f.id} type="button" aria-pressed={filter === f.id} onClick={() => setFilter(f.id)} className={filter === f.id ? "btn-primary text-xs" : "btn-secondary text-xs"}>
            {f.label}{f.id === "running" ? ` (${feed.counts.running})` : f.id === "failed" ? ` (${feed.counts.failed})` : f.id === "succeeded" ? ` (${feed.counts.succeeded})` : ""}
          </button>
        ))}
        <span className="ml-auto flex items-center gap-2 text-xs text-slate-500" aria-live="polite">
          {err ? <span className="text-red-400">{err}</span> : paused ? "Paused" : `Updated ${clock(feed.at)} UTC, every ${LIVE_POLL_MS / 1000} s`}

