// Cyrus admin Live tab: build capacity at a glance (queue depth, time in line p50/p80, run time p50/p80, concurrency,
// the priority mix per builder, the AI circuit breaker) plus the alerts set by cyrus_capacity_alert_* (Audit & settings).
// Read-only. Uses only the admin portal's shared classes (dark and light from app/admin/admin-shell.css).
import { Badge } from "@/components/ui/primitives";
import type { CapacityPanel } from "@/lib/cyrus/builder/capacity-pure";

const s = (v: number | null | undefined) => (v === null || v === undefined ? "–" : v < 90 ? `${v}s` : `${(v / 60).toFixed(1)}m`);
const mix = (o: { system: number; interactive: number; batch: number }) => `${o.interactive} user · ${o.batch} batch${o.system ? ` · ${o.system} system` : ""}`;

export function CapacityPanelView({ panel }: { panel: CapacityPanel }) {
  const t = panel.total;
  return (
    <section className="card mb-4 p-4" aria-label="Build capacity" data-testid="cyrus-live-capacity">
      <div className="mb-2 flex flex-wrap items-baseline gap-3">
        <h3 className="text-sm font-semibold">Build capacity</h3>
        <span className="text-xs text-slate-500">{t.running} of {t.concurrency || "?"} slots busy ({mix(t.runningByClass)}) · {t.queued} waiting ({mix(t.queuedByClass)})</span>
      </div>
      {panel.alerts.length > 0 && (
        <ul className="mb-3 space-y-1" role="alert">
          {panel.alerts.map((a, i) => <li key={i} className="flex items-start gap-2 text-xs"><Badge tone={a.level === "urgent" ? "red" : "amber"}>{a.level}</Badge><span>{a.text}</span></li>)}
        </ul>
      )}
      <div className="overflow-x-auto">
        <table className="w-full text-xs">
          <thead>
            <tr className="text-left text-slate-500">
              <th scope="col">Builder</th><th scope="col">Slots</th><th scope="col">Running</th><th scope="col">Waiting</th><th scope="col">In line p50 / p80</th><th scope="col">Run p50 / p80</th><th scope="col">AI</th>
            </tr>
          </thead>
          <tbody>
            {panel.workers.map((w) => (
              <tr key={w.label}>
                <td>{w.label}{!w.ok ? <> <Badge tone="red">down</Badge></> : null}</td>
                <td>{w.concurrency ?? "–"}{w.reserve ? ` (${w.reserve} kept for users)` : ""}{w.suggested !== null && w.concurrency !== null && w.suggested !== w.concurrency ? <span className="text-slate-500"> · safe {w.suggested}</span> : null}</td>
                <td>{mix(w.running)}</td>
                <td>{mix(w.queued)}{w.oldestQueuedSec ? <span className="text-slate-500"> · oldest {s(w.oldestQueuedSec)}</span> : null}</td>
                <td>{w.waitSec ? `${s(w.waitSec.p50)} / ${s(w.waitSec.p80)}` : "–"}<span className="text-slate-500">{w.waitSec ? ` (n=${w.waitSec.samples})` : ""}</span></td>
                <td>{w.runSec ? `${s(w.runSec.p50)} / ${s(w.runSec.p80)}` : "–"}<span className="text-slate-500">{w.runSec ? ` (n=${w.runSec.samples})` : ""}</span></td>
                <td>{w.breaker ? <Badge tone={w.breaker.state === "closed" ? "green" : "red"}>{w.breaker.state}</Badge> : "–"}{w.breaker?.trips ? <span className="text-slate-500"> · {w.breaker.trips} limit hit{w.breaker.trips === 1 ? "" : "s"}</span> : null}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <p className="mt-2 text-xs text-slate-500">Percentiles are the builder&apos;s own measurements of its recent builds (fewer than 5 = no number). Alerts: {panel.thresholds.queueDepth ? `${panel.thresholds.queueDepth} waiting` : "queue depth off"}, {panel.thresholds.waitP80Min ? `p80 in line ${panel.thresholds.waitP80Min} min` : "wait off"} (Audit &amp; settings, Build capacity).</p>
    </section>
  );
}

