import { CYRUS_SETTINGS, validateSettingValue } from "../lib/cyrus/admin/settings-catalog";
import { CYRUS_ENV_FLAGS, CYRUS_REMOTE_FLAGS } from "../lib/cyrus/admin/flags";

const H = (o: Partial<WorkerHealth>): WorkerHealth => ({ ok: true, running: 0, queued: 0, concurrency: 2, versions: ["1.21.11", "1.21.4"], ...o });

describe("capacity portal: dispatcher (scale-out readiness)", () => {
  it("is off unless CYRUS_MB_DISPATCH=1 AND two or more MODBUILDER_URLS", () => {
    assert.equal(dispatchWorkers({}, "k"), null);
    assert.equal(dispatchWorkers({ MODBUILDER_URLS: "http://a:1,http://b:2" }, "k"), null, "flag off");
    assert.equal(dispatchWorkers({ CYRUS_MB_DISPATCH: "1", MODBUILDER_URLS: "http://a:1" }, "k"), null, "one worker = single mode");
    assert.equal(dispatchWorkers({ CYRUS_MB_DISPATCH: "1", MODBUILDER_URLS: "http://a:1 http://b:2" }, ""), null, "no key");
    assert.deepEqual(dispatchWorkers({ CYRUS_MB_DISPATCH: "1", MODBUILDER_URLS: "http://a:1/, http://b:2 ,http://a:1, nonsense" }, "k"), [{ url: "http://a:1", key: "k" }, { url: "http://b:2", key: "k" }]);
  });
  it("scores load as (running + queued) / concurrency, skips down workers and missing versions, avoids an open breaker", () => {
    assert.equal(loadScore(H({ running: 1, queued: 1 })), 1);
    assert.equal(loadScore(H({ ok: false })), null);
    assert.equal(loadScore(null), null);
    assert.equal(loadScore(H({ versions: ["1.21.4"] }), "1.21.11"), null);
    assert.ok(loadScore(H({ capacity: { breaker: { state: "open" } } }))! > 999);
    const a: Worker = { url: "http://a", key: "k" }, b: Worker = { url: "http://b", key: "k" };
    assert.equal(chooseWorker([{ w: a, health: H({ running: 2, queued: 3 }) }, { w: b, health: H({ running: 1 }) }]), b);
    assert.equal(chooseWorker([{ w: a, health: H({}) }, { w: b, health: H({}) }]), a, "ties go to the first listed");
    assert.equal(chooseWorker([{ w: a, health: null }, { w: b, health: H({ ok: false }) }]), null);
  });
  it("places by load, keeps a build sticky, sends a change to its base build's worker, finds unknown ids by asking", async () => {
    const workers: Worker[] = [{ url: "http://w1", key: "k" }, { url: "http://w2", key: "k" }];
    const load: Record<string, WorkerHealth> = { "http://w1": H({ running: 2, queued: 2 }), "http://w2": H({ running: 0 }) };
    const has: Record<string, Set<string>> = { "http://w1": new Set(["mbold1"]), "http://w2": new Set() };
    let healthCalls = 0, hasCalls = 0, t = 0;
    const d = createDispatcher({
      workers, now: () => t, healthTtlMs: 5000,
      health: async (w) => { healthCalls++; return load[w.url]; },
      has: async (w, id) => { hasCalls++; return has[w.url].has(id); },
    });
    const w = await d.place("mbnew1", { mcVersion: "1.21.11" });
    assert.equal(w.url, "http://w2", "least loaded");
    assert.equal((await d.workerFor("mbnew1"))?.url, "http://w2", "sticky");
    assert.equal(hasCalls, 0, "sticky answers without asking");
    // a change of a build that lives on the busy worker goes there anyway (its workspace is there)
    const c = await d.place("mbchange1", { baseBuildId: "mbold1", mcVersion: "1.21.11" });
    assert.equal(c.url, "http://w1");
    assert.ok(hasCalls >= 1, "found the base build by asking");
    assert.equal(await d.workerFor("mbnobody"), null);
    // health is cached per worker
    const before = healthCalls;
    await d.pick("1.21.11"); await d.pick("1.21.11");
    assert.equal(healthCalls, before, "cached within the TTL");
    t += 6000;
    await d.pick("1.21.11");
    assert.equal(healthCalls, before + 2, "refreshed after the TTL");
  });
  it("falls back to the first worker when none answers (the request then fails like a single offline worker would)", async () => {
    const workers: Worker[] = [{ url: "http://w1", key: "k" }, { url: "http://w2", key: "k" }];
    const d = createDispatcher({ workers, health: async () => { throw new Error("down"); }, has: async () => false });
    assert.equal((await d.pick()).url, "http://w1");
  });
  it("bounds the sticky map", async () => {
    const workers: Worker[] = [{ url: "http://w1", key: "k" }, { url: "http://w2", key: "k" }];
    const d = createDispatcher({ workers, maxSticky: 3, health: async () => H({}), has: async () => false });
    for (const id of ["a1", "a2", "a3", "a4"]) d.remember(id, workers[0]);
    assert.equal(d.known("a1"), null);
    assert.equal(d.known("a4")?.url, "http://w1");
  });
});

describe("capacity portal: queue wording (truthful, no fake ETAs)", () => {
  const q = (o: Record<string, unknown>) => queueFacts({ priority: "interactive", position: 1, ahead: 0, running: 2, concurrency: 2, state: "next", waitSec: { p50: null, p80: null, samples: 0 }, retryAt: null, aiRetries: 0, ...o } as never);
  it("an older build service (no queue facts): place in line only", () => {
    assert.deepEqual(queueLine({ queuePosition: 3 }), { label: "Waiting for a free builder", detail: "In line, position 3. Nothing is spent until it starts.", state: "unknown" });
    assert.equal(queueLine({ queuePosition: 0 }).detail, "Nothing is spent until it starts.");
    assert.equal(queueLine(null).label, "Waiting for a free builder");
  });
  it("next in line: 'Starting soon' only when the measured wait is short; no number without measurements", () => {
    assert.equal(queueLine({ queue: q({ waitSec: { p50: 40, p80: 70 } }) }).label, "Starting soon");
    const unk = queueLine({ queue: q({}) });
    assert.equal(unk.label, "Next in line");
    assert.doesNotMatch(unk.detail, /\d/, "no number at all without a measurement");
    assert.match(queueLine({ queue: q({ waitSec: { p50: 200, p80: 380 } }) }).detail, /usually about 3–6 min/);
  });
  it("waiting: builds ahead + the measured range", () => {
    const l = queueLine({ queue: q({ state: "waiting", position: 4, ahead: 3, waitSec: { p50: 400, p80: 700 } }) });
    assert.equal(l.label, "Waiting for a free builder");
    assert.equal(l.detail, "3 builds are ahead of yours; usually about 7–12 min until it starts. Nothing is spent until it starts.");
    assert.match(queueLine({ queue: q({ state: "waiting", position: 2, ahead: 1 }) }).detail, /^1 build is ahead of yours\. Nothing/);
  });
  it("AI busy: calm, automatic, nothing charged", () => {
    const now = Date.parse("2026-10-14T10:00:00Z");
    const l = queueLine({ queue: q({ state: "ai_wait", retryAt: "2026-10-14T10:02:00Z" }) }, now);
    assert.equal(l.label, "Waiting for the AI");
    assert.match(l.detail, /Cyrus will try again by itself in about 2 min/);
    assert.match(l.detail, /Nothing is charged for the wait/);
  });
  it("waitPhrase rounds to minutes and never shows p80 below p50", () => {
    assert.equal(waitPhrase(null, 100), null);
    assert.equal(waitPhrase(20, 50), "under a minute");
    assert.equal(waitPhrase(150, 150), "about 3 min");
    assert.equal(waitPhrase(300, 100), "about 5 min");
  });
  it("queueFacts drops anything malformed", () => {
    const f = queueFacts({ position: -1, ahead: "x", state: "bogus", waitSec: { p50: NaN, p80: 12.6 }, retryAt: "nope" } as never);
    assert.deepEqual(f, { position: 0, ahead: 0, state: "waiting", waitSec: { p50: null, p80: 13 }, retryAt: null });
  });
  it("plan screen outlook from /health capacity", () => {
    const cap = (o: Record<string, unknown>) => ({ concurrency: 2, capacity: { running: { system: 0, interactive: 1, batch: 1 }, queued: { system: 0, interactive: 0, batch: 3 }, runSec: { p50: 160, p80: 300 }, breaker: { state: "closed" }, ...o } });
    assert.equal(planCapacity(null), null);
    assert.equal(planCapacity({ concurrency: 2 }), null, "older image: say nothing");
    assert.deepEqual(planCapacity(cap({})), { state: "busy", ahead: 0, waitSec: { p50: 80, p80: 150 } }, "batch in line does not count against a user build");
    assert.deepEqual(planCapacity(cap({ running: { interactive: 1 } })), { state: "free", ahead: 0, waitSec: { p50: 0, p80: 0 } });
    assert.equal(planCapacity(cap({ breaker: { state: "open" } }))!.state, "ai_busy");
    assert.deepEqual(planCapacity(cap({ runSec: { p50: null, p80: null } }))!.waitSec, { p50: null, p80: null });
    assert.equal(planCapacityLine(planCapacity(cap({ running: { interactive: 0 } }))), "A builder is free: it starts right away.");
    assert.equal(planCapacityLine(planCapacity(cap({ queued: { interactive: 3 } }))), "3 builds ahead of yours, usually about 5–10 min before it starts.");
    assert.equal(planCapacityLine(planCapacity(cap({ runSec: { p50: null, p80: null } }))), "Next for a free builder.");
    assert.equal(planCapacityLine(null), null);
  });
});

describe("capacity portal: admin panel, alerts, money rule, settings", () => {
  const health = (o: Record<string, unknown> = {}) => ({ ok: true, running: 2, queued: 4, concurrency: 2, capacity: { running: { system: 0, interactive: 1, batch: 1 }, queued: { system: 0, interactive: 1, batch: 3 }, reserveInteractive: 1, suggestedConcurrency: 3, priority: true, waitingForAi: 0, oldestQueuedSec: 300, runSec: { p50: 150, p80: 300, samples: 20 }, waitSec: { p50: 60, p80: 720, samples: 30 }, breaker: { state: "closed", until: null, trips: 0 }, warnings: [] , ...o } });
  it("sums the priority mix across builders and raises the configured alerts", () => {
    const p = capacityPanel([{ label: "worker 1", health: health() }, { label: "worker 2", health: null }], { queueDepth: 4, waitP80Min: 10 });
    assert.deepEqual(p.total.queuedByClass, { system: 0, interactive: 1, batch: 3 });
    assert.equal(p.total.running, 2);
    assert.equal(p.total.concurrency, 2);
    const texts = p.alerts.map((a) => a.text);
    assert.ok(texts.some((t) => /worker 2 is not answering/.test(t)));
    assert.ok(texts.some((t) => /4 builds are waiting in line \(alert at 4\)/.test(t)));
    assert.ok(texts.some((t) => /waited up to 12 min in line at p80/.test(t)));
  });
  it("thresholds 0 = those alerts off; breaker and AI waits always show", () => {
    const p = capacityPanel([{ label: "builder", health: health({ breaker: { state: "open", until: "2026-10-14T12:10:00.000Z", trips: 2 }, waitingForAi: 2 }) }], { queueDepth: 0, waitP80Min: 0 });
    const texts = p.alerts.map((a) => a.text);
    assert.ok(texts.some((t) => /rate-limited or busy \(breaker open until 12:10 UTC\)/.test(t)));
    assert.ok(texts.some((t) => /2 builds waiting for an AI retry/.test(t)));
    assert.ok(!texts.some((t) => /waiting in line|in line at p80/.test(t)));
  });
  it("an older image (no capacity block) still shows running/queued and says why there is nothing more", () => {
    const p = capacityPanel([{ label: "builder", health: { ok: true, running: 1, queued: 2, concurrency: 2 } }], { queueDepth: 6, waitP80Min: 10 });
    assert.deepEqual(p.workers[0].queued, { system: 0, interactive: 2, batch: 0 });
    assert.ok(p.alerts.some((a) => /without the capacity queue/.test(a.text)));
  });
  it("capacity and AI-unavailable failures are never charged and never use a free failure", () => {
    const cfg = { chargeRefused: true, chargeCancelled: true, freeFailures: 3, failedChargePct: 50, tokensPerUsd: 500, minSpend: 5, mult: { katara: 1, saka: 1, yakko: 1 } } as never;
    for (const code of ["ai_unavailable", "capacity"]) {
      assert.deepEqual(settleCharge({ status: "failed", errorCode: code, costUsd: 0.4, model: "saka", freeFailuresUsed: 99 }, cfg), { charge: 0, reason: "failed_infra" });
    }
    assert.deepEqual([...INFRA_FAILURE_CODES], ["ai_unavailable", "capacity"]);
    assert.equal(settleCharge({ status: "failed", errorCode: "compile", costUsd: 0.4, model: "saka", freeFailuresUsed: 99 }, cfg).reason, "failed_over_limit", "other failures unchanged");
  });
  it("the capacity settings are in the catalogue with PLACEHOLDER defaults and validated ranges", () => {
    for (const k of CAPACITY_SETTING_KEYS) {
      const def = CYRUS_SETTINGS.find((s) => s.key === k);
      assert.ok(def, k);
      assert.equal(def!.default, CAPACITY_SETTING_DEFAULTS[k]);
      assert.match(def!.description, /PLACEHOLDER/);
    }
    assert.equal(CAPACITY_SETTING_DEFAULTS.cyrus_capacity_account_max_active, "2");
    assert.deepEqual(validateSettingValue("cyrus_capacity_account_max_active", "0"), { ok: false, error: "At least 1." });
    assert.deepEqual(validateSettingValue("cyrus_capacity_account_max_active", "4"), { ok: true, value: "4" });
    assert.deepEqual(validateSettingValue("cyrus_capacity_alert_queue_depth", "0"), { ok: true, value: "0" });
  });
  it("the new switches are listed (dispatch is risky; build-service knobs say where to see them)", () => {
    assert.equal(CYRUS_ENV_FLAGS.find((f) => f.key === "CYRUS_MB_DISPATCH")?.risky, true);
    assert.ok(CYRUS_ENV_FLAGS.find((f) => f.key === "CYRUS_CAPACITY_UI"));
    for (const k of ["MB_CONCURRENCY", "MB_PRIORITY", "MB_RESERVE_INTERACTIVE", "MB_ACCOUNT_MAX_ACTIVE", "MB_QUEUE_MAX", "MB_AI_RETRIES"]) assert.ok(CYRUS_REMOTE_FLAGS.find((f) => f.key === k), k);
  });
});

