  it("every relative markdown link in docs/cyrus resolves (file and heading)", () => {
    const bad: string[] = [];
    for (const f of docFiles()) {
      const text = rd(f).replace(/```[\s\S]*?```/g, "");
      for (const m of text.matchAll(/\[[^\]]*\]\(([^)\s]+)\)/g)) {
        const href = m[1];
        if (/^(https?:|mailto:|\/)/.test(href)) continue;
        const [target, anchor] = href.split("#");
        const abs = target ? path.normalize(path.join(path.dirname(f), target)) : f;
        if (!existsSync(path.join(ROOT, abs))) { bad.push(`${f}: ${href}`); continue; }
        if (anchor && abs.endsWith(".md") && !anchorsOf(abs).has(anchor)) bad.push(`${f}: ${href} (no such heading)`);
      }
    }
