    for (let k = 0; k < 600 && done.size < ids.length; k++) {
      for (const id of ids) if (!done.has(id)) { const r = await api("GET", `/builds/${id}`); if (r.status === "succeeded" || r.status === "failed") done.set(id, { status: r.status, finishedAt: Date.now() }); }
      try { const st = fs.readFileSync(`/proc/${proc!.pid}/status`, "utf8").match(/VmRSS:\s+(\d+)/); if (st) peakRss = Math.max(peakRss, Number(st[1])); } catch { /* not linux */ }
